def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list):
        raise TypeError("pieces must be a list")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    if style not in ["semver", "pep440"]:
        raise ValueError("style must be either 'semver' or 'pep440'")

    if style == "semver":
        return ".".join(str(piece) for piece in pieces)
    elif style == "pep440":
        return ".".join(str(piece) for piece in pieces) + ".dev0"
    else:
        raise ValueError("Invalid style")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if "+" in pieces:
        return "."
    else:
        return "+"

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Command must be a string")
        if not command:
            raise ValueError("Command cannot be empty")
    if not isinstance(args, (list, tuple)):
        args = [args]
    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("Argument must be a string")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("Current working directory must be a string")
    if env is not None and not isinstance(env, dict):
        raise ValueError("Environment must be a dictionary")
    if not isinstance(verbose, bool):
        raise ValueError("Verbose flag must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("Hide stderr flag must be a boolean")

    # Build the command string
    command_str = " ".join(commands)
    if args:
        command_str += " " + " ".join(args)

    # Set the current working directory
    if cwd is not None:
        os.chdir(cwd)

    # Set the environment variables
    if env is not None:
        for key, value in env.items():
            os.environ[key] = value

    # Run the command
    try:
        if verbose:
            print("Running command:", command_str)
        result = subprocess.run(command_str, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if hide_stderr:
            result.stderr = ""
        return result.stdout.decode("utf-8")
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Command failed with exit code {}: {}".format(e.returncode, command_str)) from e

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def wrapper(*args, **kwargs):
        try:
            return method(*args, **kwargs)
        except Exception as e:
            print(f"Error handling VCS {vcs}: {e}")
    return wrapper

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    for root, dirs, files in os.walk(self.root_path):
        for file in files:
            file_path = os.path.join(root, file)
            if not os.path.isfile(file_path):
                continue

            if validate_objects:
                try:
                    self.validate_object(file_path)
                    good_objects += 1
                except InvalidObjectError:
                    if show_warnings:
                        print(f"Invalid object found: {file_path}")

            if check_digests:
                try:
                    self.validate_digest(file_path)
                except InvalidDigestError:
                    if show_warnings:
                        print(f"Invalid digest found: {file_path}")

            num_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        version_parts = version.split(".")
        if len(version_parts) != 3:
            raise ValueError("Invalid version format")
        major, minor, patch = version_parts
        if not major.isdigit() or not minor.isdigit() or not patch.isdigit():
            raise ValueError("Invalid version format")
        major = int(major)
        minor = int(minor)
        patch = int(patch)
        if patch == 9:
            if minor == 9:
                major += 1
                minor = 0
                patch = 0
            else:
                minor += 1
                patch = 0
        else:
            patch += 1
        return f"{major}.{minor}.{patch}"
    except ValueError as e:
        raise ValueError("Invalid version format") from e

