def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    try:
        import argparse
        import borgmatic

        # Get the command-line argument parsers for borgmatic
        parser = argparse.ArgumentParser()
        borgmatic.cli.add_args(parser)

        # Introspect the parsers to generate the bash completion script
        script = ""
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for subparser in action._name_parser_map.values():
                    script += f"complete -W '{subparser.choices}' {subparser.prog}\n"
            else:
                script += f"complete -W '{action.choices}' {action.prog}\n"

        return script

    except ImportError:
        return ""

def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        size = size.upper()
        if size.endswith("K"):
            return int(size[:-1]) * 1000
        elif size.endswith("M"):
            return int(size[:-1]) * 1000000
        elif size.endswith("G"):
            return int(size[:-1]) * 1000000000
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid file size")

def _dictsum(dicts):
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key not in result:
                result[key] = value
            else:
                result[key] += value
    return result

