def dict_insert(dic, val, key, *keys):
    """
    Insert a value of a nested key into a dictionary.

    :param dic: The dictionary to insert the nested key value into.
    :param val: The value to insert into the dictionary.
    :param key: The first key in the chain of keys that will store the value.
    :param keys: The sub keys in the keys chain.
    """
    if not isinstance(dic, dict):
        raise TypeError("The first argument must be a dictionary.")
    if not isinstance(val, (int, str, float, bool)):
        raise TypeError("The second argument must be a value of type int, str, float, or bool.")
    if not isinstance(key, str):
        raise TypeError("The third argument must be a string.")
    if not all(isinstance(k, str) for k in keys):
        raise TypeError("The fourth argument must be a list of strings.")

    current_dict = dic
    for k in keys:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]
    current_dict[key] = val

    return dic

