        if not isinstance(ir_workspace, InfraredWorkspace):
            raise ValueError("ir_workspace must be an InfraredWorkspace object")
        if not isinstance(ir_plugin, InfraredPlugin):
            raise ValueError("ir_plugin must be an InfraredPlugin object")
        if not isinstance(playbook_path, str):
            raise ValueError("playbook_path must be a string")
        if verbose is not None and not isinstance(verbose, int):
            raise ValueError("verbose must be an integer")
        if extra_vars is not None and not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dict")
        if ansible_args is not None and not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dict")

        # Build the ansible-playbook command
        command = ["ansible-playbook", playbook_path]
        if verbose is not None:
            command.append("-" + str(verbose))
        if extra_vars is not None:
            for key, value in extra_vars.items():
                command.append("-e")
                command.append(f"{key}={value}")
        if ansible_args is not None:
            for key, value in ansible_args.items():
                command.append(f"--{key}")
                command.append(value)

        # Run the command
        result = ir_workspace.run_command(command)

        # Return the result
        return result
    except Exception as e:
        raise e

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    try:
        for key, value in values_dict.items():
            if key in self.arg_types[parser_name]:
                values_dict[key] = self.arg_types[parser_name][key](value)
    except KeyError:
        pass
    except ValueError:
        raise ValueError(f"Invalid value for argument {key}: {value}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        with open(os.path.join(plugin_dir, "plugin.spec"), "r") as f:
            spec = yaml.safe_load(f)
    except FileNotFoundError:
        raise ValueError(f"Plugin spec file not found in {plugin_dir}")
    except yaml.YAMLError:
        raise ValueError(f"Invalid YAML format in plugin spec file {plugin_dir}/plugin.spec")

    flatten_dict = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f"{key}.{subkey}"] = subvalue
        else:
            flatten_dict[key] = value

    return flatten_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.environ.get("CONFIG_PATH"):
        os.environ["CONFIG_PATH"] = "/path/to/config.ini"
    return os.environ["CONFIG_PATH"]

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    return path[len(root):]
